code='''def transform(grid):
    out = [row[:] for row in grid]
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    rows = {}
    cols = {}
    for r, c in pts:
        rows.setdefault(r, []).append(c)
        cols.setdefault(c, []).append(r)
    # The aligned pair defines the main line.
    candidates = []
    for r, cs in rows.items():
        if len(cs) >= 2:
            candidates.append((max(cs)-min(cs), 'h', r, min(cs), max(cs)))
    for c, rs in cols.items():
        if len(rs) >= 2:
            candidates.append((max(rs)-min(rs), 'v', c, min(rs), max(rs)))
    _, orient, axis, lo, hi = max(candidates)
    if orient == 'h':
        for c in range(lo, hi+1):
            if out[axis][c] == 0: out[axis][c] = 3
        for r, c in pts:
            if r != axis:
                for rr in range(min(r, axis)+1, max(r, axis)):
                    if out[rr][c] == 0: out[rr][c] = 3
    else:
        for r in range(lo, hi+1):
            if out[r][axis] == 0: out[r][axis] = 3
        for r, c in pts:
            if c != axis:
                for cc in range(min(c, axis)+1, max(c, axis)):
                    if out[r][cc] == 0: out[r][cc] = 3
    return out
'''
